// Generated by `npm run chat:probe -- --from-trace` (T-0174) from 2026-10-17.jsonl:1 (catalog agent-ui--croupier).
// Keyless: the recorded model rounds replay through the real produce(), then the probe checks run with
// no browser. The browser leg is `npm run chat:probe -- --replay croupier-haiku-rename-halts.json` from this folder.
import { readFileSync } from 'node:fs'
import { expect, it } from 'vitest'
import { parseProbeFixture } from '../model.ts'
import { offlineReplay } from '../trace.ts'

// T-0328: live round 9 (2026-10-17-r9-matrix :1, Haiku 5.5, cluster A). Round 1 built a Slider bet Card on ask-1
// (BET_TABLE_MISSING), round 2 rebuilt it as a correct CardTable on table-1, and the T-0317 rule judged round 2
// SURFACE_DROPPED for ask-1; the forced round 3 resent table-1 and the turn halted. Kim 2026-10-17: a surface rebuilt
// under a new id within the same turn is not a drop, so round 2 ships its CardTable on table-1 and ask-1 never ships.
const lines = (record) => record.lines.map((l) => JSON.parse(l))

it('croupier-haiku-rename-halts: a repair that rebuilds the flagged ask-1 as table-1 ships the CardTable', async () => {
  const fixture = parseProbeFixture(readFileSync(new URL('./croupier-haiku-rename-halts.json', import.meta.url), 'utf8'))
  const report = await offlineReplay(fixture, process.cwd())
  expect(report.failed).toEqual([])
  const shipped = lines(report.records[0])
  expect(shipped.map((l) => l.a2uiMeta?.error).filter((e) => e !== undefined)).toEqual([])
  expect(shipped.find((l) => l.a2uiMeta?.trace !== undefined)?.a2uiMeta.trace.rounds).toBe(2)
  expect(shipped.filter((m) => m.createSurface !== undefined).map((m) => m.createSurface.surfaceId)).toEqual(['table-1'])
  const components = shipped.flatMap((m) => (m.updateComponents?.surfaceId === 'table-1' ? m.updateComponents.components : []))
  expect(components.some((c) => c.component === 'CardTable')).toBe(true)
  expect(shipped.some((m) => Object.values(m).some((b) => b?.surfaceId === 'ask-1'))).toBe(false)
})
